import {relayOrigin} from './transport.mjs';
const $=id=>document.getElementById(id),canvas=$('game-canvas'),ctx=canvas.getContext('2d',{alpha:false});
let file,romHash='',worker,active=false,mode='',currentRole='solo',keys=0,paused=false,sound=true,audio,nextAudio=0,generation=0,exportPending=false,dbPromise,writeQueue=Promise.resolve();
const cache=new Map(),lines=[];let saveContext;
const stateText={loading:'正在加载模拟器…',auth_sent:'正在认证连接…',waiting:'房间已创建，等待对手…',connected:'双方已连接，准备同步…',synchronizing:'正在校准并同步游戏…',playing_solo:'单人游戏中 · 按 Enter 开始',playing_online:'联机游戏中 · 同步已完成'};
const errors={INVALID_ROM:'请选择有效的 .gba 游戏文件（最大 32 MB）。',INVALID_CODE:'请输入有效的 8 位房间码。',ROM_MISMATCH:'双方的游戏文件不同。请使用字节完全相同的 ROM。',CONFIG_MISMATCH:'游戏版本或模拟器配置不同。双方刷新同一网址后重建房间。',PROTOCOL_MISMATCH:'协议版本不同。请双方刷新同一网址。',ROOM_FULL:'这个房间已经有两位玩家。',ROOM_EXPIRED:'房间已过期，请重新创建。',TOKEN_EXPIRED:'认证已过期，请重新创建或加入房间。',PEER_DISCONNECTED:'对手已断开连接，本次联机已结束。',HEARTBEAT_TIMEOUT:'网络连接超时，本次联机已结束。',SERVER_SHUTDOWN:'中继服务已重启，本次联机已结束。',TRANSPORT_ERROR:'无法连接中继服务，请检查网络和 Relay 地址。',RELAY_HTTP_UNREACHABLE:'无法访问房间服务，请检查网络、Relay 地址及跨域设置。',RELAY_HTTP_TIMEOUT:'房间服务响应超时，请稍后重试。',SAVE_SIZE_MISMATCH:'存档大小与此游戏不匹配。请选择正确的电池存档。',CORE_CALIBRATION_TIMEOUT:'双方网络校准超时，已停止游戏。请检查网络后重建房间。',CORE_SYNC_FAILURE:'模拟器报告同步错误，游戏已停止。可下载诊断日志。',CORE_LINK_FAILED:'模拟器联机初始化失败，游戏已停止。',BACKPRESSURE:'网络发送积压，已停止本次联机。',ORIGIN_REJECTED:'Relay 未允许当前网页地址。请在服务端配置允许的网页来源。',SESSION_STOPPED:'游戏已结束。'};
function log(text){lines.push(`${new Date().toISOString()} ${String(text).slice(0,2000)}`);if(lines.length>250)lines.shift();}
function showError(reason){$('error').textContent=errors[reason]||`运行失败：${String(reason).slice(0,100)}。请下载诊断日志。`;$('error').hidden=false;log(reason);}
function refresh(){for(const id of ['solo','host','join'])$(id).disabled=!file||active;for(const id of ['choose-rom','game-version','relay','join-code'])$(id).disabled=active;$('stop').disabled=!active;$('pause').disabled=!active||mode!=='solo';$('import-save').disabled=!file||active;$('save-slot').disabled=active;$('export-save').disabled=!file||(active&&mode!=='solo');$('power').classList.toggle('on',active);$('mode-label').textContent=active?(mode==='solo'?'SINGLE PLAYER':'MULTI-PAK LINK'):'待机';}
const hash=async bytes=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),v=>v.toString(16).padStart(2,'0')).join('');
function database(){return dbPromise??=new Promise((resolve,reject)=>{const r=indexedDB.open('advance-wars-gba-online',1);r.onupgradeneeded=()=>r.result.createObjectStore('saves');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
const saveKey=(hash,slot)=>`aw-web-1:${hash}:${slot}`;
async function getSave(hash,slot){const key=saveKey(hash,slot);if(cache.has(key))return cache.get(key);try{const db=await database();const value=await new Promise((r,j)=>{const q=db.transaction('saves').objectStore('saves').get(key);q.onsuccess=()=>r(q.result);q.onerror=()=>j(q.error);});if(value)cache.set(key,value);return value;}catch{log('SAVE_STORAGE_UNAVAILABLE');$('save-status').textContent='浏览器存储不可用，请及时导出存档。';}}
function storeSave(hash,slot,buffer){const key=saveKey(hash,slot);cache.set(key,buffer);writeQueue=writeQueue.catch(()=>{}).then(async()=>{const db=await database();await new Promise((r,j)=>{const tx=db.transaction('saves','readwrite');tx.objectStore('saves').put(buffer,key);tx.oncomplete=r;tx.onerror=()=>j(tx.error);});}).then(()=>{$('save-status').textContent=`已保存${slot==='solo'?'单人':slot==='p0'?'玩家 1':'玩家 2'}电池存档 · ${new Date().toLocaleTimeString('zh-CN')}`;}).catch(()=>{$('save-status').textContent='本地自动保存失败，请立即导出存档备份。';log('SAVE_WRITE_FAILED');});}
function download(data,name,type='application/octet-stream'){const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function audioStart(){const Audio=globalThis.AudioContext||globalThis.webkitAudioContext;if(!Audio)return;audio??=new Audio();await audio.resume();nextAudio=audio.currentTime;}
function playAudio(buffer,rate){if(!sound||!audio||audio.state!=='running')return;const p=new Int16Array(buffer),n=p.length/2;if(!n||n>8192||rate<8000||rate>192000)return;if(nextAudio>audio.currentTime+.25)return;const b=audio.createBuffer(2,n,rate);for(let c=0;c<2;c++){const d=b.getChannelData(c);for(let i=0;i<n;i++)d[i]=p[i*2+c]/32768;}const src=audio.createBufferSource();src.buffer=b;src.connect(audio.destination);nextAudio=Math.max(nextAudio,audio.currentTime+.015);src.start(nextAudio);nextAudio+=n/rate;}
function setKeys(v){keys=v;worker?.postMessage({type:'keys',keys});}
function clearKeys(){setKeys(0);}
function finish(w){if(w!==worker)return;worker=null;active=false;paused=false;clearKeys();$('pause').textContent='暂停';$('game-status').textContent='游戏已结束，可重新开始';$('local-status').textContent='已断开';$('peer-status').textContent='已断开';$('latency').textContent='— ms';audio?.suspend();w.terminate();refresh();}
function handle(m,w,context){if(worker!==w)return;
 if(m.type==='state'){$('game-status').textContent=stateText[m.state]||m.state;log(`state=${m.state}`);if(['waiting','auth_sent'].includes(m.state))$('local-status').textContent=m.state==='waiting'?'已认证':'认证中';if(['connected','synchronizing','playing_online'].includes(m.state)){$('local-status').textContent='已连接';$('peer-status').textContent='已连接';}}
 else if(m.type==='video'){if(m.w>512||m.h>512||m.buffer.byteLength!==m.w*m.h*4)return;canvas.width=m.w;canvas.height=m.h;ctx.putImageData(new ImageData(new Uint8ClampedArray(m.buffer),m.w,m.h),0,0);$('screen-empty').hidden=true;}
 else if(m.type==='audio')playAudio(m.buffer,m.rate);
 else if(m.type==='room'){currentRole=m.role===0?'p0':'p1';$('save-slot').value=currentRole;$('invite-code').textContent=m.code;$('invite-box').hidden=false;$('local-status').textContent=`玩家 ${m.role+1}`;}
 else if(m.type==='save'){storeSave(context.hash,m.role,m.buffer);if(exportPending){exportPending=false;download(m.buffer,`${context.game}-${m.role}.sav`);}}
 else if(m.type==='rtt')$('latency').textContent=`${m.ms} ms`;
 else if(m.type==='log')log(m.text);
 else if(m.type==='metrics')log(`metrics ${JSON.stringify(m)}`);
 else if(m.type==='error')showError(m.reason);
 else if(m.type==='stopped')finish(w);
}
async function start(nextMode){if(active||!file)return;const mine=++generation;mode=nextMode;active=true;paused=false;exportPending=false;$('error').hidden=true;$('invite-box').hidden=true;refresh();$('game-status').textContent='正在准备游戏…';
 try{if(nextMode!=='solo')relayOrigin($('relay').value);await audioStart().catch(()=>log('AUDIO_UNAVAILABLE'));const rom=await file.arrayBuffer();const hashValue=romHash;const saves={};for(const slot of ['solo','p0','p1']){const b=await getSave(hashValue,slot);if(b)saves[slot]=b.slice(0);}if(mine!==generation)return;currentRole=nextMode==='solo'?'solo':nextMode==='host'?'p0':'p1';$('save-slot').value=currentRole;saveContext={hash:hashValue,game:$('game-version').value};const w=new Worker(new URL('./emulator-worker.mjs',import.meta.url),{type:'module'});worker=w;w.onmessage=({data})=>handle(data,w,saveContext);w.onerror=e=>{showError('WORKER_ERROR');log(e.message);finish(w);};w.postMessage({type:'start',mode:nextMode,game:$('game-version').value,rom,saves,relay:$('relay').value,code:$('join-code').value},[rom]);w.postMessage({type:'audio',enabled:sound});log(`start mode=${nextMode} game=${$('game-version').value} romSHA256=${hashValue}`);
 }catch(e){if(mine!==generation)return;showError(e.message);if(worker)finish(worker);else{active=false;refresh();$('game-status').textContent='启动失败，请检查提示。';}}
}
$('choose-rom').onclick=()=>$('rom-file').click();
$('rom-file').onchange=async e=>{const chosen=e.target.files[0];if(!chosen)return;try{const b=await chosen.arrayBuffer();if(b.byteLength<192||b.byteLength>32*1024*1024||new Uint8Array(b)[0xb2]!==0x96)throw Error('INVALID_ROM');const h=await hash(b);file=chosen;romHash=h;$('file-label').replaceChildren(document.createTextNode(chosen.name));const small=document.createElement('small');small.textContent=`${(b.byteLength/1024/1024).toFixed(2)} MB · 已准备`; $('file-label').append(small);$('file-info').textContent=`SHA-256 ${h.slice(0,12)}… · 文件仅在本地读取`;$('game-status').textContent='准备完成 · 点击开始单人游戏';$('error').hidden=true;$('save-status').textContent='单人、玩家 1、玩家 2 的电池存档分别保存。';refresh();}catch(e){showError(e.message);}};
$('solo').onclick=()=>start('solo');$('host').onclick=()=>start('host');$('join').onclick=()=>start('join');
$('stop').onclick=()=>{++generation;if(worker){worker.postMessage({type:'stop'});$('game-status').textContent='正在安全结束并保存…';}else{active=false;audio?.suspend();refresh();$('game-status').textContent='已取消启动';}};
$('pause').onclick=()=>{if(mode!=='solo'||!worker)return;paused=!paused;clearKeys();worker.postMessage({type:'pause',paused});$('pause').textContent=paused?'继续':'暂停';$('game-status').textContent=paused?'已暂停':'单人游戏中';};
$('sound').onclick=async()=>{sound=!sound;$('sound').textContent=`声音 ${sound?'开':'关'}`;$('sound').setAttribute('aria-pressed',String(sound));worker?.postMessage({type:'audio',enabled:sound});if(sound&&active)await audioStart().catch(()=>{});else await audio?.suspend();};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('screen').requestFullscreen();}catch{$('game-status').textContent='当前浏览器不支持全屏。';}};
$('copy-code').onclick=async()=>{try{await navigator.clipboard.writeText($('invite-code').textContent);$('copy-code').textContent='已复制';setTimeout(()=>$('copy-code').textContent='复制',1500);}catch{$('game-status').textContent='复制受限，请手动复制上面的房间码。';}};
$('diagnose').onclick=async()=>{const b=$('diagnose');b.disabled=true;try{const origin=relayOrigin($('relay').value),start=performance.now();const r=await fetch(origin+'/health',{credentials:'omit',signal:AbortSignal.timeout(10000)});const body=await r.json();if(!r.ok||body.status!=='ok'||body.protocol!=='aw-relay-1')throw Error('INVALID_RELAY_RESPONSE');$('diagnostic-result').textContent=`服务可用 · ${Math.round(performance.now()-start)} ms · aw-relay-1`;}catch(e){$('diagnostic-result').textContent=`检测失败：${errors[e.message]||'无法访问服务，请检查网络与跨域配置。'}`;}finally{b.disabled=false;}};
$('download-log').onclick=()=>download(`AW Web alpha 0.3\nUser agent: ${navigator.userAgent}\n${lines.join('\n')}`,`aw-web-diagnostic-${Date.now()}.txt`,'text/plain;charset=utf-8');
$('help-open').onclick=()=>$('help-dialog').showModal();$('help-close').onclick=()=>$('help-dialog').close();
$('import-save').onclick=()=>$('save-file').click();$('save-file').onchange=async e=>{if(active||!file)return;const b=await e.target.files?.[0]?.arrayBuffer();if(!b)return;if(b.byteLength<512||b.byteLength>1024*1024){showError('SAVE_SIZE_MISMATCH');return;}storeSave(romHash,$('save-slot').value,b);e.target.value='';};
$('export-save').onclick=async()=>{if(!file)return;if(active&&mode==='solo'){exportPending=true;worker?.postMessage({type:'export'});return;}const slot=$('save-slot').value;const b=await getSave(romHash,slot);if(b)download(b,`${$('game-version').value}-${slot}.sav`);else $('save-status').textContent='此槽位还没有存档。请先在游戏内保存，再结束游戏。';};
const keyMap={ArrowUp:4,ArrowDown:5,ArrowLeft:6,ArrowRight:7,KeyZ:8,KeyX:0,Enter:3,ShiftLeft:2,ShiftRight:2,KeyA:10,KeyS:11};
addEventListener('keydown',e=>{if(!active||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||$('help-dialog').open||!(e.code in keyMap))return;e.preventDefault();if(!paused)setKeys(keys|(1<<keyMap[e.code]));});addEventListener('keyup',e=>{if(e.code in keyMap)setKeys(keys&~(1<<keyMap[e.code]));});addEventListener('blur',clearKeys);
for(const b of document.querySelectorAll('[data-key]')){b.onpointerdown=e=>{e.preventDefault();if(!active||paused)return;b.setPointerCapture(e.pointerId);setKeys(keys|(1<<+b.dataset.key));};for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>setKeys(keys&~(1<<+b.dataset.key)));}
document.addEventListener('visibilitychange',()=>{clearKeys();if(document.hidden&&active){if(mode==='solo'&&!paused){paused=true;worker?.postMessage({type:'pause',paused:true});$('pause').textContent='继续';$('game-status').textContent='切换页面后已暂停，请点击继续';}else if(mode!=='solo'){$('error').textContent='联机页面进入后台，已结束会话。请双方保持网页在前台并重建房间。';$('error').hidden=false;$('stop').click();}}});
refresh();
